 const tones=[['#6f8b5a','#708154','#786552'],['#59634e','#807568','#59695c'],['#668365','#867f70','#587b7a']][index];addIsland(0,0,39,34,tones[0],'main');addIsland(85,-48,23,20,tones[1],'hamlet');addIsland(-93,45,28,22,tones[2],'wild');
 // distant rocky stacks
 for(let i=0;i<17;i++){let a=i*2.4,dist=100+(i%5)*20;let rock=new THREE.Mesh(new THREE.ConeGeometry(5+(i%3)*3,9+(i%4)*4,6),mat(i%2?'#425957':'#68786b'));rock.position.set(Math.cos(a)*dist,-1+((i%3)*.2),Math.sin(a)*dist);rock.castShadow=true;scene.add(rock);islandObjects.push(rock)}
 createNpc('Mariner Sora',-7,1,8,'quest');createNpc('Witch Mirelle',3,1,11,'witch');createNpc('Harbor Warden',10,1,5,'portal');createBoat();for(let i=0;i<4;i++)makeHouse(-12+i*7,19,i);
 player.position.set(0,0,0);cameraYaw=0;updateMinimap();spawnEnemies(5);
}
function createNpc(name,x,y,z,type){const g=new THREE.Group();g.position.set(x,y,z);g.userData={name,type};const robe=new THREE.Mesh(new THREE.CylinderGeometry(.37,.5,1.25,8),mat(type==='witch'?'#39283e':'#58746b'));robe.position.y=.66;g.add(robe);const head=new THREE.Mesh(new THREE.SphereGeometry(.24,10,8),mat('#d9ae88'));head.position.y=1.52;g.add(head);const hat=new THREE.Mesh(new THREE.ConeGeometry(.38,.62,8),mat(type==='witch'?'#281d30':'#8c6040'));hat.position.y=1.95;g.add(hat);const badge=new THREE.Mesh(new THREE.SphereGeometry(.1,8,6),mat('#ffa454',.3,.3));badge.position.set(.25,1.15,.22);g.add(badge);scene.add(g);if(type==='quest')npc=g;islandObjects.push(g)}
function createBoat(){boat=new THREE.Group();const hull=new THREE.Mesh(new THREE.CylinderGeometry(.5,.8,13,8),mat('#4b3024'));hull.rotation.z=Math.PI/2;hull.position.y=.2;boat.add(hull);const mast=new THREE.Mesh(new THREE.CylinderGeometry(.12,.17,9,7),mat('#b38a58'));mast.position.y=4.5;boat.add(mast);const sail=new THREE.Mesh(new THREE.PlaneGeometry(5,5),mat('#e1d7b8'));sail.position.set(0,4.7,.1);boat.add(sail);boat.position.set(12,-.8,12);scene.add(boat)}
function makeHouse(x,z,i){const g=new THREE.Group();g.position.set(x,0,z);let wall=new THREE.Mesh(new THREE.BoxGeometry(4.5,3.4,3.6),mat(i%2?'#68443a':'#625449'));wall.position.y=1.7;g.add(wall);let roof=new THREE.Mesh(new THREE.ConeGeometry(3.9,2.4,4),mat('#29272a'));roof.position.y=4;roof.rotation.y=Math.PI/4;g.add(roof);let door=new THREE.Mesh(new THREE.BoxGeometry(.9,1.9,.15),mat(i===2?'#8f4929':'#312c29'));door.position.set(0,.95,1.9);door.userData={door:true,index:i};g.add(door);if(i===2){let portal=new THREE.Mesh(new THREE.TorusGeometry(1.2,.12,8,20),new THREE.MeshBasicMaterial({color:'#f47b3e'}));portal.position.set(0,2.3,-2);g.add(portal)}islandObjects.push(g);scene.add(g)}
function spawnEnemies(count){if(!scene)return;for(let i=0;i<count;i++){const type=i===4?'Cinder Captain':'Shoreline Raider';const g=new THREE.Group();const color=i===4?'#5c3229':'#7b5541';let torso=new THREE.Mesh(new THREE.CylinderGeometry(.34,.42,1.1,8),mat(color));torso.position.y=1;torso.castShadow=true;g.add(torso);let head=new THREE.Mesh(new THREE.SphereGeometry(.25,10,8),mat('#b78364'));head.position.y=1.72;g.add(head);let band=new THREE.Mesh(new THREE.BoxGeometry(.52,.09,.08),mat('#e69a56'));band.position.set(0,1.8,.22);g.add(band);let blade=new THREE.Mesh(new THREE.BoxGeometry(.07,.8,.08),mat('#b7c3bd',.25,.7));blade.position.set(.5,.9,0);blade.rotation.z=-.5;g.add(blade);let x=(Math.random()-.5)*53,z=(Math.random()-.5)*42;if(Math.hypot(x,z)<13){x+=20}g.position.set(x,0,z);scene.add(g);enemies.push({group:g,type,hp:i===4?360:65,max:i===4?360:65,level:i===4?45:Math.max(3,state.level+2),attack:0,aggro:false,alive:true,boss:i===4})}}
function makeEffect(pos,color,size=1,duration=.55,type='burst'){const m=new THREE.Mesh(type==='ring'?new THREE.TorusGeometry(size,.12,8,28):type==='slash'?new THREE.TorusGeometry(size,.16,5,20,Math.PI):new THREE.IcosahedronGeometry(size,1),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.8,wireframe:type==='burst'}));m.position.copy(pos);m.position.y=Math.max(.15,m.position.y);if(type==='ring')m.rotation.x=Math.PI/2;if(type==='slash'){m.rotation.x=.8;m.rotation.z=Math.random()*2}scene.add(m);effects.push({mesh:m,life:duration,max:duration,scale:type==='ring'?2.8:1.9});return m}

