function makeEffect(pos,color,size=1,duration=.55,type='burst'){const m=new THREE.Mesh(type==='ring'?new THREE.TorusGeometry(size,.12,8,28):type==='slash'?new THREE.TorusGeometry(size,.16,5,20,Math.PI):new THREE.IcosahedronGeometry(size,1),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.8,wireframe:type==='burst'}));m.position.copy(pos);m.position.y=Math.max(.15,m.position.y);if(type==='ring')m.rotation.x=Math.PI/2;if(type==='slash'){m.rotation.x=.8;m.rotation.z=Math.random()*2}scene.add(m);effects.push({mesh:m,life:duration,max:duration,scale:type==='ring'?2.8:1.9});return m}
function levelXp(l){return Math.floor(130+Math.pow(l,1.34)*18)}
function save(){try{localStorage.setItem('emberwake-save',JSON.stringify({...state,activeQuest:activeQuest?{...activeQuest}:null,questCount}))}catch(e){}}
function load(){try{const s=JSON.parse(localStorage.getItem('emberwake-save'));if(s){Object.assign(state,s);activeQuest=s.activeQuest||null;questCount=s.questCount||0}}catch(e){}}
function toast(msg){const t=document.createElement('div');t.className='toast';t.innerHTML=msg;$('#toasts').append(t);setTimeout(()=>t.remove(),2700)}
function updateHud(){const xpMax=levelXp(state.level),pct=state.hp/(100+state.stats.Defense*4)*100;$('#playerName').textContent=state.name;$('#levelText').textContent=state.level;$('#xpText').textContent=state.xp.toLocaleString();$('#xpNeeded').textContent=xpMax.toLocaleString();$('#xpFill').style.width=`${Math.min(100,state.xp/xpMax*100)}%`;const maxHp=100+state.stats.Defense*4,maxEnergy=100+state.stats.Melee*2+state.stats.Fruit*2;state.hp=Math.min(state.hp,maxHp);state.energy=Math.min(state.energy,maxEnergy);$('#healthNum').textContent=`${Math.ceil(state.hp)} / ${maxHp}`;$('#healthFill').style.width=`${clamp(state.hp/maxHp*100,0,100)}%`;$('#energyNum').textContent=`${Math.floor(state.energy)} / ${maxEnergy}`;$('#energyFill').style.width=`${clamp(state.energy/maxEnergy*100,0,100)}%`;$('#beliText').textContent=state.beli.toLocaleString();$('#fragmentText').textContent=state.fragments;$('#masteryText').textContent=state.mastery;$('#masteryXp').textContent=`${state.masteryXP.toLocaleString()} / ${Math.floor(600+state.mastery*8).toLocaleString()}`;$('#masteryFill').style.width=`${state.masteryXP/(600+state.mastery*8)*100}%`;$('#meterText').textContent=`${Math.floor(state.meter)}%`;$('#meterFill').style.width=`${state.meter}%`;$('#questTitle').textContent=activeQuest?activeQuest.name:'No active contract';$('#questDesc').textContent=activeQuest?`Defeat ${activeQuest.goal} ${activeQuest.enemy}${activeQuest.goal>1?'s':''}`:'Speak with Mariner Sora to accept a contract';$('#questProgressText').textContent=activeQuest?`${questCount} / ${activeQuest.goal}`:'—';$('#questReward').textContent=activeQuest?`+${activeQuest.xp} XP · ${activeQuest.beli} Beli`:'CONTRACT BOARD';$('#questFill').style.width=activeQuest?`${questCount/activeQuest.goal*100}%`:'0%';$('.quest-action').textContent=activeQuest?'TRACK CONTRACT  ↗':'VIEW CONTRACTS  ↗';$('#seaName').textContent=seas[state.sea].name.toUpperCase();$('#coords').textContent=`${Math.round(player?.position.x||0)}, ${Math.round(player?.position.z||0)}`;$('#combatMessage').textContent=state.transformed?'Flamebound Surge active · 50% damage reduction':'Elemental Reflex active · Aura pierces immunity';$$('.ability').forEach(b=>{const k=b.dataset.skill,req={f:50,x:100,c:200,v:300}[k];b.classList.toggle('locked',!!req&&state.mastery<req);if(k==='v'&&state.transformed)b.querySelector('b').textContent='REVERSION';else if(k==='v')b.querySelector('b').textContent='ASCENSION'});}
function addXP(amount){state.xp+=amount;let up=false;while(state.level<3000&&state.xp>=levelXp(state.level)){state.xp-=levelXp(state.level);state.level++;state.statPoints+=3;state.hp=100+state.stats.Defense*4;state.energy=100+state.stats.Melee*2+state.stats.Fruit*2;up=true}if(up){toast(`<b>LEVEL UP!</b> You are now level ${state.level} · +3 stat points`);makeEffect(player.position.clone().add(new THREE.Vector3(0,1,0)),0xffc674,2,1,'ring')}updateHud();save()}
function addMastery(amount){state.masteryXP+=amount;while(state.mastery<600&&state.masteryXP>=600+state.mastery*8){state.masteryXP-=600+state.mastery*8;state.mastery++;if([50,100,200,300].includes(state.mastery))toast(`<b>MASTERY ${state.mastery}</b> · A new Hellfire technique is within reach`)}updateHud()}
function damageEnemy(e,damage,knock=1){if(!e.alive)return;e.hp-=damage;state.meter=clamp(state.meter+damage*.14,0,100);e.aggro=true;e.group.position.add(new THREE.Vector3().subVectors(e.group.position,player.position).normalize().multiplyScalar(.45*knock));makeEffect(e.group.position.clone().add(new THREE.Vector3(0,1,0)),0xff8341,.25,.3,'burst');if(e.hp<=0){e.alive=false;makeEffect(e.group.position.clone().add(new THREE.Vector3(0,1,0)),0xff983f,e.boss?2.5:1.2,.9,'ring');scene.remove(e.group);state.kills++;state.beli+=e.boss?1100:90;state.fragments+=e.boss?12:1;state.inventory['Candy Corn']=(state.inventory['Candy Corn']||0)+(e.boss?8:1);addXP(e.boss?420:55+e.level*3);addMastery(e.boss?55:18);if(activeQuest&&e.type===activeQuest.enemy){questCount++;if(questCount>=activeQuest.goal)completeQuest()}toast(e.boss?'<b>CAPTAIN DEFEATED</b> · Bounty and fragments secured':'<b>RAIDER DOWN</b> · + Beli · + Candy Corn');if(e.boss)setTimeout(()=>{if(gameStarted)spawnEnemies(1)},12000);else setTimeout(()=>spawnEnemies(1),4500);if(state.transformed)state.meter=clamp(state.meter-5,0,100);updateHud();save()}else if(Math.random()<.38){const d=document.createElement('div');d.className='toast';d.style.padding='5px 9px';d.textContent=`−${Math.round(damage)}`;d.style.position='fixed';d.style.left=`${50+Math.random()*12-6}%`;d.style.top='43%';$('#toasts').append(d);setTimeout(()=>d.remove(),600)}}
function completeQuest(){if(!activeQuest)return;let q=activeQuest;toast(`<b>CONTRACT COMPLETE</b> · +${q.xp} XP · +${q.beli} Beli`);addXP(q.xp);state.beli+=q.beli;state.fragments+=5;activeQuest=null;questCount=0;updateHud();save()}
function acceptQuest(){if(activeQuest){toast('Contract tracked. Find the marked enemies nearby.');return}const q=quests[Math.min(state.sea,quests.length-1)];activeQuest={...q};questCount=0;toast(`<b>CONTRACT ACCEPTED</b> · ${q.name}`);updateHud();save()}
