function updateMinimap(){const label=$('.map-label');if(label)label.textContent=(state.island||seas[state.sea].islands[0][0]).toUpperCase();const p=$('.mini-player');if(p){p.style.left=`${50+clamp(player.position.x/80,-35,35)}%`;p.style.top=`${50+clamp(player.position.z/70,-35,35)}%`}}
function nearestNpc(){let best=null,d=5;for(const o of islandObjects)if(o.userData?.type){const n=o.position.distanceTo(player.position);if(n<d){best=o;d=n}}return best}
function interact(){const n=nearestNpc();if(n){if(n.userData.type==='quest'){if(activeQuest)toast('Contract accepted · defeat the marked foes');else acceptQuest()}else if(n.userData.type==='witch')openPanel('event');else openPanel('map');return}if(boat&&boat.position.distanceTo(player.position)<7){toast('The harbor skiff is ready · open the world map to sail between islands');openPanel('map');return}toast('No one is close enough to speak')}
function openPanel(type){const box=$('#panelContent');let content='',title='';if(type==='character'){title='Character';content=`<p class="panel-lede">A quick view of your Ashen Tide record.</p><div class="panel-grid"><div class="panel-stat"><small>LEVEL</small><b>${state.level}</b></div><div class="panel-stat"><small>STAT POINTS</small><b>${state.statPoints}</b></div><div class="panel-stat"><small>RACE</small><b>${state.race}</b></div><div class="panel-stat"><small>MASTERY</small><b>${state.mastery}</b></div></div><h3>Distribute stats</h3>${Object.entries(state.stats).map(([k,v])=>`<div class="stat-row"><span>${k} · ${v}</span><button data-stat="${k}" ${state.statPoints<1?'disabled':''}>+1</button></div>`).join('')}<button class="panel-action" data-action="rename">Change pirate name</button>`}
 else if(type==='inventory'){title='Inventory';content=`<p class="panel-lede">Collected gear and event finds.</p><div class="inventory-list">${Object.entries(state.inventory).map(([name,count])=>`<div class="inventory-item"><span>✦ ${name}</span><b>× ${count}</b>${name==='Hellfire Gas'?'<small>EQUIPPED MUTATION</small>':''}</div>`).join('')}</div><button class="panel-action" data-action="fruit-roll">Roll fruit · 1,000 Beli</button>`}
 else if(type==='map'){title='Three Seas';content=`<p class="panel-lede">Sail to discovered islands. Later seas require a higher level.</p>${seas.map((sea,si)=>`<h3>${sea.name} <small>· ${sea.theme}</small></h3><div class="island-list">${sea.islands.map(([name,desc,x,z],ii)=>{const req=si===0?[1,100,220,1][ii]:si===1?[700,830,960,700][ii]:[1500,1630,1770,1500][ii],locked=state.level<req;return `<button class="island-card" data-island="${si}:${ii}" ${locked?'disabled':''}><b>${name}</b><span>${desc}</span><small>${locked?`REQUIRES LV ${req}`:`SAIL · ${req===1?'OPEN':`LV ${req}+`}`}</small></button>`}).join('')}</div>`).join('')}`}
 else if(type==='quests'){title='Contracts';content=`<p class="panel-lede">Take on local work to earn Beli, fragments, and experience.</p><div class="panel-card"><b>${activeQuest?activeQuest.name:'Ash on the Shore'}</b><p>${activeQuest?`${questCount}/${activeQuest.goal} ${activeQuest.enemy}`:'Defeat 3 Shoreline Raiders'}</p><button class="panel-action" data-action="quest">${activeQuest?'TRACK CURRENT CONTRACT':'ACCEPT CONTRACT'}</button></div><p class="panel-note">Defeated raiders drop Candy Corn during the Harvest Moon event.</p>`}
 else if(type==='codex'){title='Mutation Codex';content=`<p class="panel-lede">${fruitCodex.length} known fruits · selected mutation: <b>${state.equipped}</b></p><div class="codex-list">${fruitCodex.map(([name,rarity,desc])=>`<div><b>${name}</b><small>${rarity}</small><p>${desc}</p></div>`).join('')}</div>`}
 else if(type==='event'){title='Harvest Moon';content=`<p class="panel-lede">The veil is thin. Trick-or-treat for event goods and face the Pit's infernal raid.</p><div class="event-banner"><b>HARVEST MOON · UPDATE 30.1</b><span>Event currencies: ${state.inventory['Candy Corn']||0} Candy Corn · ${state.inventory['Pumpkin Bits']||0} Pumpkin Bits</span></div><h3>Witch Mirelle's exchange</h3><button class="panel-action" data-action="candy">Trade 8 Candy Corn for 1 Pumpkin Bit</button><button class="panel-action" data-action="treat">Trick-or-treat · 15 Beli</button><h3>The Pit · Hellfire Raid</h3><p>Defeat the Cinder Captain for fragments, event candy, and mastery. This local raid instance is available from the Second Sea.</p><button class="panel-action" data-island="1:3" ${state.level<700?'disabled':''}>Enter The Pit · Second Sea</button>`}
 else{title='Settings';content=`<p class="panel-lede">Local game settings and save management.</p><button class="panel-action" data-action="sound">${state.muted?'Enable':'Mute'} sound effects</button><button class="panel-action" data-action="save">Save now</button><button class="panel-action danger" data-action="reset">Reset local save</button><p class="panel-note">Progress is stored in this browser only. Multiplayer and cloud saves are not connected.</p>`}
 box.innerHTML=`<div class="eyebrow">ASHEN TIDE · ${seas[state.sea].name.toUpperCase()}</div><h2>${title}</h2>${content}`;$('#scrim').classList.add('open');box.querySelectorAll('[data-stat]').forEach(b=>b.onclick=()=>addStat(b.dataset.stat));box.querySelectorAll('[data-island]').forEach(b=>b.onclick=()=>{const [s,i]=b.dataset.island.split(':').map(Number);sail(s,i)});box.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>panelAction(b.dataset.action));$$('.rail-btn').forEach(b=>b.classList.toggle('active',b.dataset.panel===type))}
function closePanel(){$('#scrim').classList.remove('open');$$('.rail-btn').forEach((b,i)=>b.classList.toggle('active',i===0))}
function addStat(key){if(state.statPoints<1)return;state.statPoints--;state.stats[key]++;updateHud();save();openPanel('character')}
function panelAction(action){if(action==='rename'){renamePlayer();return}if(action==='quest'){closePanel();acceptQuest();return}if(action==='sound'){toggleSound();openPanel('settings');return}if(action==='save'){save();toast('Progress saved on this device');return}if(action==='reset'){if(confirm('Delete this browser save and restart?')){localStorage.removeItem('emberwake-save');location.reload()}return}if(action==='candy'){if((state.inventory['Candy Corn']||0)<8){toast('You need 8 Candy Corn');return}state.inventory['Candy Corn']-=8;state.inventory['Pumpkin Bits']=(state.inventory['Pumpkin Bits']||0)+1;toast('Exchange complete · +1 Pumpkin Bit');save();openPanel('event');return}if(action==='treat'){if(state.beli<15){toast('Not enough Beli');return}state.beli-=15;state.inventory['Candy Corn']=(state.inventory['Candy Corn']||0)+1;toast('Trick-or-treat! +1 Candy Corn');updateHud();save();openPanel('event');return}if(action==='fruit-roll'){if(state.beli<1000){toast('Not enough Beli');return}state.beli-=1000;let fruit=fruitCodex[Math.floor(Math.random()*fruitCodex.length)][0];state.inventory[fruit]=(state.inventory[fruit]||0)+1;toast(`Fruit found · <b>${fruit}</b>`);updateHud();save();openPanel('inventory')}}
function sail(si,ii){const req=si===0?[1,100,220,1][ii]:si===1?[700,830,960,700][ii]:[1500,1630,1770,1500][ii];if(state.level<req){toast(`Requires level ${req} to sail there`);return}state.sea=si;state.island=seas[si].islands[ii][0];buildWorld(si);player.position.set(ii%2?7:-5,0,ii>1?7:-3);updateHud();updateMinimap();closePanel();toast(`Arrived at ${state.island} · ${seas[si].name}`);save()}
function renamePlayer(){const next=prompt('Choose your pirate name (2–16 characters):',state.name);if(next&&next.trim()){state.name=next.trim().slice(0,16);updateHud();save()}}
function toggleSound(){state.muted=!state.muted;$('#soundBtn').textContent=state.muted?'×':'♫';save()}

