 {name:'First Sea',level:1,theme:'Verdant islands · warm shallows',islands:[['Ember Cove','Starter island · Ashwood coast',0,0],['Mossbell Wilds','Forest sanctuary · hidden spring',100,700],['Glasswake Cliffs','Volcanic ruins · cave passage',220,1550],['Witchlight Hamlet','Harvest Moon · trick-or-treat',0,2500]]},
 {name:'Second Sea',level:700,theme:'Storm frontier · ancient ruins',islands:[['Cinderwatch','Black-sand port · raider camp',0,0],['Tempest Reach','Floating cliffs · storm shrine',130,950],['The Gloaming','Twilight forest · haunted manor',260,1800],['The Pit','Lava arena · Hellfire raid',0,2800]]},
 {name:'Third Sea',level:1500,theme:'Far horizon · wild magic',islands:[['Dawnspire','Sunlit city · sky gardens',0,0],['Maw of Tides','Sunken reef · abyssal cave',130,1100],['Elderbloom','Ancient canopy · spirit grove',270,2100],['Moonfall Reach','Harvest Moon · great pumpkin',0,3000]]}
];
const fruitCodex=[['Rocket','Common','Quick propulsion and aerial bursts.'],['Spin','Common','Whirling attacks and evasive movement.'],['Blade','Common','Close-range conjured blades.'],['Spring','Common','Rebounding strikes and leaps.'],['Bomb','Common','Timed explosive area attacks.'],['Smoke','Common','Concealing clouds and lift.'],['Spike','Common','Grounded thorn volleys.'],['Flame','Uncommon','Persistent fire and flight.'],['Falcon','Uncommon','Aerial dive and feather volleys.'],['Ice','Uncommon','Freezing paths and control.'],['Sand','Uncommon','Sinking swirls and desert rush.'],['Dark','Uncommon','Gravity wells and pulls.'],['Diamond','Uncommon','Defensive crystal mantle.'],['Light','Rare','High-speed beam traversal.'],['Rubber','Rare','Elastic strikes and resilience.'],['Barrier','Rare','Shaping protective walls.'],['Ghost','Rare','Spectral copies and haunting.'],['Magma','Rare','Lava pools and volcanic impact.'],['Quake','Legendary','Wide seismic shockwaves.'],['Buddha','Legendary','Colossal defensive form.'],['Love','Legendary','Charming companions and hearts.'],['Spider','Legendary','Web traps and tether movement.'],['Sound','Legendary','Resonant waves and tempo.'],['Phoenix','Legendary','Rebirth, healing and flight.'],['Portal','Legendary','Short-range spatial gates.'],['Rumble','Legendary','Lightning arcs and storms.'],['Pain','Legendary','Repelling force bursts.'],['Blizzard','Legendary','Cyclone and freezing wind.'],['Gravity','Mythical','Meteor pull and crushing force.'],['Mammoth','Mythical','Armored charge transformation.'],['T-Rex','Mythical','Predatory roar and pounce.'],['Dough','Mythical','Elastic traps and relentless combos.'],['Shadow','Mythical','Living darkness and wraiths.'],['Venom','Mythical','Toxic pools and dragon form.'],['Control','Mythical','A spatial field that reshapes combat.'],['Spirit','Mythical','Twin spirit companions.'],['Dragon','Mythical','Dragon form and elemental breath.'],['Leopard','Mythical','Fast close-range beast form.'],['Kitsune','Mythical','Foxfire and swift transformation.'],['Gas','Mythical','Toxic cloud control and mutation.'],['Magnet','Mythical','Metallic orbit and magnetic pull.'],['Hellfire Gas','Mythical · Mutation','Infernal orange flame mutation; resonance builds over time and damage.']];
const quests=[{name:'Ash on the Shore',enemy:'Shoreline Raider',goal:3,xp:240,beli:380},{name:'Whispers in the Pines',enemy:'Grove Stalker',goal:4,xp:420,beli:620},{name:'The Cinder Captain',enemy:'Cinder Captain',goal:1,xp:850,beli:1400}];
let scene,camera,renderer,clock,player,playerParts=[],enemies=[],effects=[],projectiles=[],islandObjects=[],npc,boat,water,raycaster,mouse=new THREE.Vector2(0,0),targetPoint=new THREE.Vector3(0,0,1),cameraYaw=0,cameraPitch=.2,keys={},lastAttack=0,lastDash=0,jumpCount=0,velY=0,lastSave=0,gameStarted=false,activeQuest=null,questCount=0,dayTime=0,seaLevel=0,enemySpawnTimer=0,skillCooldowns={},joyVector={x:0,y:0};
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
function init3D(){
 scene=new THREE.Scene();scene.background=new THREE.Color('#a9c5bf');scene.fog=new THREE.FogExp2('#9bb4a8',.0016);
