 renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;$('#game').appendChild(renderer.domElement);
 clock=new THREE.Clock();raycaster=new THREE.Raycaster();
 scene.add(new THREE.HemisphereLight('#d5eee3','#283e3c',2.1));let sun=new THREE.DirectionalLight('#ffdfb0',3);sun.position.set(-80,120,45);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-120;sun.shadow.camera.right=120;sun.shadow.camera.top=120;sun.shadow.camera.bottom=-120;scene.add(sun);scene.userData.sun=sun;
 const oceanGeo=new THREE.PlaneGeometry(2000,2000,100,100);oceanGeo.rotateX(-Math.PI/2);water=new THREE.Mesh(oceanGeo,new THREE.MeshPhysicalMaterial({color:'#247c83',roughness:.25,metalness:.1,transparent:true,opacity:.88,clearcoat:.6,clearcoatRoughness:.2}));water.position.y=-1.2;water.receiveShadow=true;scene.add(water);water.userData.base=oceanGeo.attributes.position.array.slice();
 createPlayer();buildWorld(state.sea||0);setupInputs();updateHud();animate();
}
function createPlayer(){player=new THREE.Group();scene.add(player);const coat=mat('#274b4a'),skin=mat('#d7a47c'),dark=mat('#1b2828'),gold=mat('#dca15b',.4,.4);const body=new THREE.Mesh(new THREE.CylinderGeometry(.34,.44,1.05,9),coat);body.position.y=1.05;body.castShadow=true;player.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.28,12,10),skin);head.position.y=1.77;head.castShadow=true;player.add(head);const hair=new THREE.Mesh(new THREE.SphereGeometry(.3,10,7,0,Math.PI*2,0,Math.PI*.6),dark);hair.position.set(0,1.85,-.03);player.add(hair);const scarf=new THREE.Mesh(new THREE.TorusGeometry(.31,.07,6,12),gold);scarf.rotation.x=Math.PI/2;scarf.position.y=1.49;player.add(scarf);for(let side of [-1,1]){const limb=new THREE.Mesh(new THREE.CapsuleGeometry(.12,.58,3,7),side===-1?skin:coat);limb.position.set(side*.44,1.13,0);limb.rotation.z=side*.09;limb.castShadow=true;player.add(limb);playerParts.push(limb);const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.15,.55,3,7),dark);leg.position.set(side*.19,.42,0);leg.castShadow=true;player.add(leg);playerParts.push(leg)}
 const sword=new THREE.Mesh(new THREE.BoxGeometry(.075,.95,.1),gold);sword.position.set(.66,1.05,-.05);sword.rotation.z=-.42;player.add(sword);player.userData.sword=sword;player.position.set(0,0,0);
}
function clearWorld(){for(const o of islandObjects)scene.remove(o);islandObjects=[];enemies.forEach(e=>scene.remove(e.group));enemies=[];if(npc)scene.remove(npc);if(boat)scene.remove(boat);}
function addIsland(cx,cz,rx,rz,color,detail){const group=new THREE.Group();group.position.set(cx,0,cz);scene.add(group);islandObjects.push(group);const shore=new THREE.Mesh(new THREE.CylinderGeometry(1,1,.75,48,1),mat('#c5a77a'));shore.scale.set(rx,1,rz);shore.position.y=-.45;shore.castShadow=true;shore.receiveShadow=true;group.add(shore);const land=new THREE.Mesh(new THREE.CylinderGeometry(1,1,.8,48,1),mat(color));land.scale.set(rx*.91,1,rz*.91);land.position.y=-.03;land.castShadow=true;land.receiveShadow=true;group.add(land);
 // central elevation and layered ridges
 for(let i=0;i<5;i++){const a=i*2.4+.3,dist=.15+(i%2)*.2,h=5+(i%3)*2;const rock=new THREE.Mesh(new THREE.ConeGeometry(5+(i%3)*2,h,7),mat(i%2?'#536854':'#68795f'));rock.position.set(Math.cos(a)*rx*.26,h/2-.05,Math.sin(a)*rz*.25);rock.castShadow=true;group.add(rock)}
 const treeCount=detail==='hamlet'?11:18;for(let i=0;i<treeCount;i++){const a=i*2.399,rr=.3+((i*37)%57)/100;let x=Math.cos(a)*rx*rr,z=Math.sin(a)*rz*rr;if(Math.abs(x)<4&&Math.abs(z)<4)continue;const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.22,.34,2.4,6),mat('#594634'));trunk.position.set(x,1,z);trunk.castShadow=true;group.add(trunk);const leaf=new THREE.Mesh(new THREE.DodecahedronGeometry(1.7+(i%3)*.35,0),mat(i%4===0?'#ab7045':i%3===0?'#657d4b':'#42694f'));leaf.position.set(x,2.8+(i%3)*.3,z);leaf.castShadow=true;group.add(leaf)}
 // cottages and a landmark
 for(let i=0;i<3;i++){const b=new THREE.Group();let x=(i-1)*7,z=-rz*.42;b.position.set(x,.1,z);let base=new THREE.Mesh(new THREE.BoxGeometry(5,3.8,4),mat(i===1?'#795641':'#89715a'));base.position.y=1.9;base.castShadow=true;b.add(base);let roof=new THREE.Mesh(new THREE.ConeGeometry(4,2.5,4),mat('#422d29'));roof.position.set(0,4.7,0);roof.rotation.y=Math.PI/4;roof.castShadow=true;b.add(roof);const door=new THREE.Mesh(new THREE.BoxGeometry(.8,1.8,.12),mat('#2a2923'));door.position.set(0,.9,2.06);b.add(door);group.add(b)}
 const cave=new THREE.Mesh(new THREE.TorusGeometry(3,.8,7,14,Math.PI),mat('#253a37'));cave.position.set(-rx*.35,.7,rz*.2);cave.rotation.y=Math.PI/2;group.add(cave);
}
function buildWorld(index){clearWorld();seaLevel=index;state.sea=index;state.island=seas[index].islands[0][0];$('#seaName').textContent=seas[index].name.toUpperCase();$('#seasonText').textContent=index===1?'STORM SEASON':'HARVEST MOON';scene.background.set(index===1?'#839a9e':index===2?'#9b9cac':'#a9c5bf');scene.fog.color.set(index===1?'#879ba0':index===2?'#9695a7':'#9bb4a8');
 const tones=[['#6f8b5a','#708154','#786552'],['#59634e','#807568','#59695c'],['#668365','#867f70','#587b7a']][index];addIsland(0,0,39,34,tones[0],'main');addIsland(85,-48,23,20,tones[1],'hamlet');addIsland(-93,45,28,22,tones[2],'wild');
 // distant rocky stacks
 for(let i=0;i<17;i++){let a=i*2.4,dist=100+(i%5)*20;let rock=new THREE.Mesh(new THREE.ConeGeometry(5+(i%3)*3,9+(i%4)*4,6),mat(i%2?'#425957':'#68786b'));rock.position.set(Math.cos(a)*dist,-1+((i%3)*.2),Math.sin(a)*dist);rock.castShadow=true;scene.add(rock);islandObjects.push(rock)}
 createNpc('Mariner Sora',-7,1,8,'quest');createNpc('Witch Mirelle',3,1,11,'witch');createNpc('Harbor Warden',10,1,5,'portal');createBoat();for(let i=0;i<4;i++)makeHouse(-12+i*7,19,i);
