import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');
const config = await import('node:fs').then(fs => JSON.parse(fs.readFileSync(join(process.env.HOME, '.local/share/omgithub-playwright/linux.json'), 'utf8')));
const browser = await chromium.launch(config.default?.launchOptions || config.browser?.launchOptions || {});
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [], badResponses = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('response', r => { if (r.status() >= 400) badResponses.push(`${r.status()} ${r.url()}`); });
await page.goto('http://127.0.0.1:8000', { waitUntil: 'networkidle' });
console.log('title', await page.title());
console.log('initial canvas', await page.locator('#game canvas').count());
console.log('initial 404s', JSON.stringify(badResponses));
await page.locator('#playBtn').click();
await page.waitForTimeout(1000);
console.log('started', await page.locator('#startScreen').evaluate(e => e.classList.contains('hidden')));
await page.keyboard.press('w'); await page.waitForTimeout(400); await page.keyboard.press('w');
console.log('coords after move', await page.locator('#coords').textContent());
await page.locator('#questAction').click();
console.log('quest active', await page.locator('#questTitle').textContent(), await page.locator('#questProgressText').textContent());
await page.locator('[data-skill="z"]').click();
console.log('skill toast', await page.locator('#toasts').innerText());
await page.locator('#eventBtn').click();
console.log('event panel', (await page.locator('#panelContent').innerText()).includes('The Pit'));
await page.locator('[data-action="candy"]').click();
console.log('currency after trade', await page.locator('#panelContent').innerText());
await page.locator('#closePanel').click();
await page.locator('[data-panel="inventory"]').click();
console.log('inventory panel', await page.locator('#panelContent h2').textContent());
await page.locator('#closePanel').click();
await page.locator('[data-panel="map"]').click();
console.log('map options', await page.locator('[data-island]').count());
console.log('errors', JSON.stringify(errors));
console.log('bad responses', JSON.stringify(badResponses));
await page.screenshot({path:'/tmp/opencode/emberwake-captures/test-final.png'});
await browser.close();

