import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');
const fs = await import('node:fs');
const config = JSON.parse(fs.readFileSync(join(process.env.HOME, '.local/share/omgithub-playwright/linux.json'), 'utf8'));
const browser = await chromium.launch({ ...(config.browser?.launchOptions || {}), headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [], badResponses = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('requestfailed', r => badResponses.push(`${r.url()} ${r.failure()?.errorText}`));
page.on('response', r => { if (r.status() >= 400) badResponses.push(`${r.status()} ${r.url()}`); });
await page.goto('http://127.0.0.1:8000', { waitUntil: 'networkidle' });
await page.locator('#playBtn').click();
await page.locator('#game canvas').click();
await page.keyboard.down('w');
await page.waitForTimeout(900);
await page.keyboard.up('w');
console.log('movement coords', await page.locator('#coords').textContent());
console.log('movement player position', await page.evaluate(() => document.querySelector('#coords').textContent));
await page.keyboard.press('z');
await page.waitForTimeout(150);
console.log('normal ability feedback', await page.locator('#toasts').innerText());
await page.locator('[data-panel="map"]').click();
await page.locator('[data-island="0:1"]').click();
await page.waitForTimeout(100);
console.log('map arrival', await page.locator('.map-label').textContent(), 'coords', await page.locator('#coords').textContent());
await page.locator('#settingsBtn').click();
await page.locator('[data-action="save"]').click();
const saved = await page.evaluate(() => JSON.parse(localStorage.getItem('emberwake-save')));
console.log('local save', saved?.island, saved?.sea, saved?.name);
await page.reload({ waitUntil: 'networkidle' });
console.log('loaded save HUD', await page.locator('#seaName').textContent(), 'map label', await page.locator('.map-label').textContent());
console.log('errors', JSON.stringify(errors));
console.log('bad responses', JSON.stringify(badResponses));
await browser.close();

